impl BlockSimulator { // there is probably a cleaner way to describe this TM's behavior...
    pub fn new() -> Self {
        use BlockSymbol::*;
        // use RunSymbolType::*;
        Self {
            left_tape: vec![L, P, V],
            right_tape: vec![R],
            state: HigherState::LeftA,
            base_steps: 21,
            self_steps: 0
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }
}

